-- Zephras: concise original Italian adaptations of retrieved quest fields.
-- Sources: Sources-Zephras.txt. Unknown/mismatching fields remain English.
local db = WoWForeverIT_QuestIT.DataIT
db[93317] = db[93317] or {}
db[93317].title = {it = "Stagione dei granchi", enHash = {"b6089033"}}
db[93317].objectives = {it = "Raccogli 6 pezzi di Carne di Granchio di Cantovento.", enHash = {"0b6844a2"}}
db[93317].text = {it = "I granchi del Lago Cantovento si possono raccogliere solo per poche settimane ogni anno. Le attività del culto mi hanno impedito di andarci e la stagione sta finendo. Procuramene un po’: cercali sulle rive del lago e nei fiumi. Attenzione, sono più aggressivi di quanto sembrino!", enHash = {"aabf16a1"}}
db[93317].progress = {it = "Qui questa carne è comune, ma ad Anvilas e Siroccas era una prelibatezza. Quando le correnti celesti erano aperte, la gente si accalcava per comprarla durante i miei viaggi a Shen’dramar e Nuova Eldre’naar. Non torno lì da molto tempo.", enHash = {"a9bc9ec0", "fdd2245c", "ec2781f2"}}
db[93317].reward = {it = "Per tutti i venti, questa carne è magnifica! Grazie mille, $C.", enHash = {"08fd79d4", "f7035898", "5746842e"}}
db[92683] = db[92683] or {}
db[92683].title = {it = "Polvere di svolazzafarfalla", enHash = {"f9b7ca5b"}}
db[92683].objectives = {it = "Raccogli 5 dosi di Polvere di Svolazzafarfalla dalle farfalle delle pianure di Gustberry.", enHash = {"5fa1f37a"}}
db[92683].text = {it = "Le grandi farfalle vicino al frutteto producono una polvere utile in casa. Prendi questo scacciamosche e colpiscile: fuggiranno o reagiranno, ma scuotendosi lasceranno cadere la polvere. Raccogline un po’ per me.", enHash = {"1aeb050b"}}
db[92683].progress = {it = "Di solito sono docili, ma se le infastidisci possono sorprenderti.", enHash = {"32a74214"}}
db[92683].reward = {it = "Grazie! Questa polvere finisce dappertutto: potresti ritrovartela nei pantaloni per settimane. Dovevo raccoglierla da tempo, ma uscire da sola con tutti questi banditi è rischioso. A cosa mi serve? A varie cose… lascia perdere.", enHash = {"5db9d969", "4067d21d", "5e785cc7"}}
db[92684] = db[92684] or {}
db[92684].title = {it = "Calcavento davvero irascibili", enHash = {"786f72cd"}}
db[92684].objectives = {it = "Raccogli 7 Filetti di Calcavento delle Pianure dai calcavento irascibili di Gustberry.", enHash = {"b7b2bff1"}}
db[92684].text = {it = "Il raccolto è già scarso e i calcavento rubano le mie meletempesta. Riducine il numero nei campi, ma fai attenzione: quelli delle pianure sono grandi, aggressivi e possono ucciderti con un calcio. Portami della carne e preparerò un pasto caldo.", enHash = {"f2840ad8"}}
db[92684].progress = {it = "Non mangio carne vera a cena da… troppo tempo.", enHash = {"dca5ba3c"}}
db[92684].reward = {it = "Che filetti enormi! Devi aver abbattuto delle bestie davvero imponenti.", enHash = {"dbd71cb7"}}
db[93736] = db[93736] or {}
db[93736].title = {it = "Spiriti indesiderati", enHash = {"dae4f42b"}}
db[93736].objectives = {it = "Raccogli 10 Essenze di Spirito del Vento Vuoto nella Foresta di Ventombra.", enHash = {"cb2c5f08"}}
db[93736].text = {it = "I Plasmavento cercano di capire perché gli spiriti ci abbiano abbandonato e come richiamarli. Nella Foresta di Ventombra sono comparse strane creature del vento, dette “vuote”, proprio dopo la loro partenza. Disperdile e portami i resti da studiare.", enHash = {"60b9a42e"}}
db[93736].progress = {it = "La Foresta di Ventombra è pericolosa. C’è chi la dice infestata: non ne sono convinta, ma certo non è un luogo per chi manca di coraggio o preparazione.", enHash = {"cb1b8fca"}}
db[93736].reward = {it = "Queste essenze mi trasmettono una profonda inquietudine, quasi un’aura di malvagità e rimpianto.\n\n<Endaria rabbrividisce.>\n\nNon sarà piacevole studiarle.", enHash = {"502bf427", "3d2d59a3", "591d9963"}}
db[94896] = db[94896] or {}
db[94896].title = {it = "Aiuto ai profughi", enHash = {"f18c4a78"}}
db[94896].objectives = {it = "Raccogli 8 Oggetti Abbandonati tra le rovine di Ban’aethal.", enHash = {"cd00565e"}}
db[94896].text = {it = "Se vai nella Foresta di Ventombra, cerca gli oggetti lasciati a Ban’aethal. Noi profughi abbiamo dovuto fuggire nel cuore della notte, quando il villaggio ha iniziato a precipitare nel cielo. È troppo pericoloso tornarci, ma recuperare qualcosa ci aiuterebbe molto.", enHash = {"37118776"}}
db[94896].progress = {it = "Molti sono fuggiti con i soli abiti che indossavano. Ogni oggetto recuperato sarebbe prezioso.", enHash = {"c8fb54e1"}}
db[94896].reward = {it = "Grazie, $C. Restituirò questi oggetti ai loro proprietari: ci danno qualcosa da cui ricominciare.", enHash = {"c05c934a"}}
db[94897] = db[94897] or {}
db[94897].title = {it = "Il destino di una persona amata", enHash = {"f271fab5"}}
db[94897].objectives = {it = "Trova Resaan tra le rovine di Ban’aethal.", enHash = {"5b226a3e"}}
db[94897].text = {it = "Se vai a Ban’aethal, cerca il mio amato Resaan. È tornato a prendere provviste nonostante le mie suppliche. Dopo oltre una settimana temo il peggio. Riportalo a casa, se è vivo; altrimenti, ti prego, recupera il suo cimelio.", enHash = {"b84d1ac2"}}
db[94897].progress = {it = "Hai notizie di Resaan? Ti prego, $C: dopo tutto ciò che è successo, questa attesa è insopportabile.", enHash = {"4a5be6f7"}}
db[94897].reward = {it = "Gli occhi di Ealaane si riempiono di lacrime.\n\nResaan, amore mio… la nostra vita insieme sembrava appena iniziata. Grazie, $C. Ho perso la casa e il mio amore, ma questo cimelio mi aiuterà ad affrontare il dolore.", enHash = {"7b4fa5b0", "c0d1539c", "fc3f605c"}}
db[94484] = db[94484] or {}
db[94484].title = {it = "Un silenzio inquietante", enHash = {"6f18458f"}}
db[94484].objectives = {it = "Trova Elegael Thornpaw nella parte nordorientale della Foresta di Ventombra e parlagli.", enHash = {"6fc835cb"}}
db[94484].text = {it = "Un momento, $N. Dal conclave druidico nella grotta a nordest della Foresta di Ventombra non arrivano notizie da troppo tempo. Dopo la rovina di Ban’aethal e i recenti disordini, temo sia accaduto qualcosa di grave. Cerca Elegael Thornpaw e scopri come stanno.", enHash = {"fed0b371"}}
db[94484].reward = {it = "Finalmente Lotheluum ha ricevuto il messaggio! Ma dove sono gli altri rinforzi?\n\n<Elegael impallidisce mentre gli riferisci la conversazione.>\n\nDunque il messaggio non è arrivato. Siamo nei guai: dovremo cavarcela da soli, e il tempo stringe.", enHash = {"8e42eb24", "312e60f2", "0f6b7648"}}
db[93735] = db[93735] or {}
db[93735].title = {it = "Il costrutto guasto", enHash = {"9636c91b"}}
db[93735].objectives = {it = "Trova Riaani Nightwind nella parte occidentale di Valanaar.", enHash = {"2c341a42"}}
db[93735].text = {it = "I Plasmavento custodiscono i dispositivi donati dagli spiriti del vento. Dopo la loro partenza, pochi costrutti funzionano ancora. Uno di quelli di Valanaar si è guastato: raggiungi la zona occidentale della città e aiuta l’artigiano incaricato della riparazione.", enHash = {"47a37b40"}}
db[93735].reward = {it = "Riaani lavora ai meccanismi sotto le piastre del costrutto senza accorgersi di te.\n\nMaledette tempeste, dov’è il nucleo?! Hanno tolto anche il Girozefiro! È un miracolo che i venti del costrutto non si siano già dispersi!", enHash = {"a0f2251a", "580935e4", "708511fa"}}
db[93737] = db[93737] or {}
db[93737].title = {it = "Il costrutto guasto", enHash = {"9636c91b"}}
db[93737].objectives = {it = "Parla con Riaani Nightwind e ascolta ciò che ha da dirti.", enHash = {"e5fabd7a"}}
db[93737].text = {it = "Ayessa ti manda ad aiutarmi? Bene. Non so cosa possa fare qualcuno con così poca esperienza, ma lasciami uscire dalle viscere di questo costrutto e troverò qualche incarico per te.", enHash = {"ec2513b4"}}
db[93737].progress = {it = "Perché rubare questi componenti? Quasi nessuno ha altri usi pratici. Persino il Girozefiro sarebbe pressoché inutile fuori da questo dispositivo.", enHash = {"144669d7"}}
db[93737].reward = {it = "Grazie per i materiali: recuperarli non dev’essere stato facile. Ora posso riattivare il costrutto. Speriamo che la memoria sia intatta e riveli chi ha sottratto i componenti.", enHash = {"35c6ab6f", "67d9c79b", "004c8fb1"}}
db[93738] = db[93738] or {}
db[93738].title = {it = "Il costrutto guasto", enHash = {"9636c91b"}}
db[93738].objectives = {it = "Torna da Ayessa Dawnsinger a Valanaar.", enHash = {"651687cb"}}
db[93738].text = {it = "Brightwish? Dunque l’Alto Ordine voleva questi componenti. Continuano a sperimentare con la magia degli spiriti, violando i divieti dei Plasmavento. Torna da Ayessa Dawnsinger e riferisci ciò che hai scoperto: saprà come procedere.", enHash = {"e371842f"}}
db[93738].reward = {it = "È stato l’Alto Ordine a causare il guasto? Conosco Belathaan, cugino di Valennia Stormfist: sua madre era una Plasmavento. Mi delude sapere che sia coinvolto. Devo rifletterci.", enHash = {"c36e0f28", "3ade862c", "43897b00"}}
db[92698] = db[92698] or {}
db[92698].objectives = {it = "Parla con Aamelia Windfield del Costrutto Ciclone Malfunzionante.", enHash = {"305a96ee"}}
db[92698].text = {it = "Ti avvicini per ascoltare le parole sotto le piastre del gigantesco costrutto.\n\n…Errore di funzionamento… Domanda… Qual è… Funzione…\n\nI frammenti si ripetono. Forse qualcuno nei dintorni sa qualcosa di questo costrutto.", enHash = {"5d8fe5a9"}}
db[92682] = db[92682] or {}
db[92682].objectives = {it = "Raccogli 10 Meletempesta Mature e uccidi 5 Banditi Affamati nel frutteto Windfield.", enHash = {"5d0de688"}}
db[92682].text = {it = "Hai più coraggio che buon senso? Bene: finché Ferauu e i suoi non vengono a ritirare la loro parte del raccolto, lavorerai per guadagnarti i pasti. Raccogli le meletempesta di oggi e uccidi i banditi nascosti tra gli alberi. Vediamo come te la cavi.", enHash = {"7f4d4ecc"}}
db[92682].reward = {it = "Ti ho visto dalla finestra mentre abbattevi quei banditi. Niente male.", enHash = {"ddc2ce8e"}}
